import React, { useState } from "react";
import axios from "axios";
import { FaEye, FaEyeSlash } from "react-icons/fa";
import { SEO } from "../utils/SEO";

const ForgotPassword = () => {
  const [email, setEmail] = useState("");
  const [mobileNumber, setMobileNumber] = useState("");
  const [otp, setOtp] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [role, setRole] = useState("");
  const [message, setMessage] = useState("");
  const [messageType, setMessageType] = useState("");
  const [loading, setLoading] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const [otpSent, setOtpSent] = useState(false);

  const handleSendOtpOrLink = async (e) => {
    e.preventDefault();

    if (!role) {
      setMessage("Please select a role.");
      setMessageType("danger");
      return;
    }

    if (role === "user" && !mobileNumber) {
      setMessage("Please enter your mobile number.");
      setMessageType("danger");
      return;
    }

    if (role !== "user" && !email) {
      setMessage("Please enter your email.");
      setMessageType("danger");
      return;
    }

    try {
      setLoading(true);
      if (role === "user") {
        await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/users/forgot-password-send-otp`, { mobileNumber });
        setMessage("OTP sent successfully to your mobile number.");
        setMessageType("success");
        setOtpSent(true);
      } else {
        let apiUrl = "";

if (role === "centre") {
  apiUrl = `${process.env.REACT_APP_BACKEND_URL}/api/centres/forgot-password`;
} else if (role === "seller") {
  apiUrl = `${process.env.REACT_APP_BACKEND_URL}/api/sellers/forgot-password`; // Seller API
} else if (role === "admin") {
  apiUrl = `${process.env.REACT_APP_BACKEND_URL}/api/admin/forgot-password`;
}

await axios.post(apiUrl, { email });
        await axios.post(apiUrl, { email });
        setMessage("Reset link sent successfully.");
        setMessageType("success");
        setEmail("");
        setRole("");
      }
    } catch (err) {
      const errorMsg = err.response?.data?.message || "Something went wrong.";
      setMessage(errorMsg);
      setMessageType("danger");
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async (e) => {
    e.preventDefault();
    if (!otp || !newPassword) {
      setMessage("Please enter OTP and new password.");
      setMessageType("danger");
      return;
    }

    try {
      setLoading(true);
      await axios.post(`${process.env.REACT_APP_BACKEND_URL}/api/users/forgot-password-reset-with-otp`, { 
        mobileNumber, 
        otp, 
        password: newPassword 
      });
      setMessage("Password reset successful. You can now login.");
      setMessageType("success");
      setOtpSent(false);
      setMobileNumber("");
      setOtp("");
      setNewPassword("");
      setRole("");
    } catch (err) {
      const errorMsg = err.response?.data?.message || "Invalid OTP or request failed.";
      setMessage(errorMsg);
      setMessageType("danger");
    } finally {
      setLoading(false);
    }
  };
 const can = window.location.href;
  return (
<>
 <SEO
        title="How to Reset a Forgotten Password (Step-by-Step Guide)"
        description="Reset your forgotten password easily with our expert guide. Fast, secure, and simple steps to recover your account instantly."
        url={can}
      />
    <div className="container d-flex justify-content-center align-items-center min-vh-100" style={{flexDirection:"column"}}>
      <div
        className="card p-4 shadow"
        style={{ maxWidth: "400px", width: "100%" }}
      >
        <h1 className="mb-4 text-center">Forgot Password</h1>
        
        {!otpSent ? (
          <form onSubmit={handleSendOtpOrLink}>
            <div className="mb-3">
              <label className="form-label fw-semibold">Select Role</label>
              <select
                className="form-select"
                value={role}
                onChange={(e) => {
                  setRole(e.target.value);
                  setMessage("");
                }}
                disabled={loading}
              >
                <option value="">Select Role</option>
                <option value="user">User</option>
                <option value="centre">Centre</option>
                <option value="seller">Seller</option>
              </select>
            </div>

            {role === "user" ? (
              <div className="mb-3">
                <label className="form-label fw-semibold">Mobile Number</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Enter registered mobile number"
                  value={mobileNumber}
                  onChange={(e) => setMobileNumber(e.target.value)}
                  disabled={loading}
                  maxLength="10"
                />
              </div>
            ) : (
              <div className="mb-3">
                <label className="form-label fw-semibold">Email Address</label>
                <input
                  type="email"
                  className="form-control"
                  placeholder="Enter registered email"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  disabled={loading}
                />
              </div>
            )}

            <button className="btn btn-primary w-100" type="submit" disabled={loading}>
              {loading ? (
                <>
                  <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                  Sending...
                </>
              ) : (
                role === "user" ? "Send OTP" : "Send Reset Link"
              )}
            </button>
          </form>
        ) : (
          <form onSubmit={handleResetPassword}>
            <div className="mb-3">
              <label className="form-label fw-semibold">Enter OTP</label>
              <input
                type="text"
                className="form-control"
                placeholder="Enter 6-digit OTP"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                disabled={loading}
                maxLength="6"
              />
            </div>
            <div className="mb-3">
              <label className="form-label fw-semibold">New Password</label>
              <div className="position-relative">
                <input
                  type={showPassword ? "text" : "password"}
                  className="form-control"
                  placeholder="Enter new password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  disabled={loading}
                />
                <button
                  type="button"
                  className="btn btn-link position-absolute top-50 end-0 translate-middle-y text-muted text-decoration-none"
                  onClick={() => setShowPassword(!showPassword)}
                  style={{ paddingRight: "15px", zIndex: 10 }}
                >
                  {showPassword ? <FaEyeSlash /> : <FaEye />}
                </button>
              </div>
            </div>
            <button className="btn btn-primary w-100" type="submit" disabled={loading}>
              {loading ? (
                <>
                  <span className="spinner-border spinner-border-sm me-2" role="status" aria-hidden="true"></span>
                  Resetting...
                </>
              ) : (
                "Reset Password"
              )}
            </button>
            <button 
              type="button" 
              className="btn btn-link w-100 mt-2" 
              onClick={() => { setOtpSent(false); setMessage(""); }}
            >
              Back
            </button>
          </form>
        )}

        {message && (
          <div className={`alert alert-${messageType} mt-3`} role="alert">
            {message}
          </div>
        )}
      </div>

     <div className="mt-3">
      <p style={{fontSize:"18px"}}>Back to <a href="/"><u>Home</u></a></p>
     </div>
    </div>
     
     </>
  );
};

export default ForgotPassword;
